import { useMemo, useState } from 'react'
import type { MouseEvent } from 'react'
import { usePrototypeState } from '../data/prototypeStore'
import { createBehaviorGeneration, extractBehavioralSequence, fixGeneratedBehavior, generateProbabilisticActions, pauseReplay, requestValidatedReplay, resetReplay, resumeReplay, selectReplayGeneration, sendGenerationToValidator, startReplay, stopReplay, validateGeneratedBehavior } from '../data/prototypeStore'
import { Icon } from './Icon'

type TraceWorkspaceProps = { onNavigate: (event: MouseEvent<HTMLAnchorElement>, path: string) => void }

function sourceLabel(source: string) {
  return source === 'observed_real' ? 'Observed real' : source === 'simulated' ? 'Simulated' : source === 'replayed' ? 'Replayed' : 'Regenerated'
}

function SourceBadge({ source }: { source: string }) {
  return <span className={`trace-source trace-source-${source}`}>{sourceLabel(source)}</span>
}

function formatTimestamp(value: string) {
  return new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23', timeZone: 'Asia/Bangkok' }).format(new Date(value))
}

export function LogsTracesPage({ onNavigate }: TraceWorkspaceProps) {
  const state = usePrototypeState()
  const querySessionId = new URLSearchParams(window.location.search).get('session') ?? ''
  const [runFilter, setRunFilter] = useState('all')
  const [serviceFilter, setServiceFilter] = useState('all')
  const [sourceFilter, setSourceFilter] = useState('all')
  const [sessionFilter, setSessionFilter] = useState(querySessionId)
  const [search, setSearch] = useState('')
  const [dateFrom, setDateFrom] = useState('')
  const [dateTo, setDateTo] = useState('')
  const [sortKey, setSortKey] = useState<'timestamp' | 'action' | 'source'>('timestamp')
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc')
  const [activeTab, setActiveTab] = useState('Application Log')
  const [selectedSessionId, setSelectedSessionId] = useState(querySessionId)
  const filteredEvents = useMemo(() => state.traceEvents.filter((event) => {
    const searchable = JSON.stringify(event).toLowerCase()
    return (runFilter === 'all' || event.runId === runFilter) && (sourceFilter === 'all' || event.source === sourceFilter) && (serviceFilter === 'all' || event.service === serviceFilter) && (!sessionFilter || event.sessionId === sessionFilter) && (!dateFrom || event.timestamp.slice(0, 10) >= dateFrom) && (!dateTo || event.timestamp.slice(0, 10) <= dateTo) && (!search || searchable.includes(search.toLowerCase()))
  }).sort((a, b) => {
    const compared = sortKey === 'timestamp' ? a.timestamp.localeCompare(b.timestamp) : sortKey === 'action' ? a.action.localeCompare(b.action) : a.source.localeCompare(b.source)
    return compared * (sortDirection === 'asc' ? 1 : -1)
  }), [state.traceEvents, runFilter, sourceFilter, serviceFilter, sessionFilter, search, dateFrom, dateTo, sortKey, sortDirection])
  const mqttEvents = filteredEvents.filter((event) => event.protocol === 'MQTT' || event.service === 'MQTT Broker' || event.action.startsWith('mqtt_') || event.action === 'topic_discovery')
  const deviceEvents = filteredEvents.filter((event) => ['device_discovery', 'device_interaction', 'reconnect', 'disconnect'].includes(event.action) || event.deviceState)
  const sessionsForView = state.sessions.filter((session) => !sessionFilter || session.id === sessionFilter)
  const selectedSession = state.sessions.find((session) => session.id === (selectedSessionId || sessionFilter))
  const selectedSessionEvents = selectedSession ? state.traceEvents.filter((event) => event.sessionId === selectedSession.id).sort((a, b) => a.timestamp.localeCompare(b.timestamp)) : []
  const sessionStart = selectedSession?.startedAt ?? selectedSessionEvents[0]?.timestamp
  const sessionEnd = selectedSession?.status === 'Active' ? undefined : selectedSession?.endedAt ?? selectedSessionEvents.at(-1)?.timestamp
  const sessionDuration = sessionStart && sessionEnd ? `${Math.max(0, Math.round((new Date(sessionEnd).getTime() - new Date(sessionStart).getTime()) / 1000))} sec` : selectedSession ? 'In progress' : '—'
  const simulatedCount = state.traceEvents.filter((event) => event.source === 'simulated').length
  const sortButton = (key: 'timestamp' | 'action' | 'source', label: string) => <button type="button" className="logs-sort-button" onClick={() => { if (sortKey === key) setSortDirection((direction) => direction === 'asc' ? 'desc' : 'asc'); else { setSortKey(key); setSortDirection('asc') } }}>{label}{sortKey === key ? sortDirection === 'asc' ? ' ↑' : ' ↓' : ''}</button>
  const sourceCell = (event: typeof filteredEvents[number]) => <SourceBadge source={event.source} />
  const sessionCell = (sessionId: string) => <button type="button" className="table-mono-link session-filter-button" onClick={() => { setSessionFilter(sessionId); setSelectedSessionId(sessionId) }}>{sessionId}</button>

  return <div className="trace-workspace-page">
    <section className="trace-workspace-summary"><span className="trace-workspace-icon"><Icon name="activity" size={20} /></span><div><div className="section-kicker">EVENT COLLECTION</div><h2>Logs &amp; Traces</h2><p>Network and application records projected from the shared Event Store.</p></div><div className="trace-summary-stats"><span><small>TOTAL EVENTS</small><strong>{state.traceEvents.length}</strong></span><span><small>SIMULATED</small><strong>{simulatedCount}</strong></span><span><small>SESSIONS</small><strong>{state.sessions.length}</strong></span></div></section>
    {sessionFilter && <div className="trace-filter-notice"><span>SESSION FILTER</span><strong>{sessionFilter}</strong><button onClick={() => { window.history.pushState({}, '', '/logs-traces'); setSearch(''); setRunFilter('all'); setServiceFilter('all'); setSourceFilter('all'); setDateFrom(''); setDateTo(''); setSessionFilter(''); setSelectedSessionId(''); window.dispatchEvent(new PopStateEvent('popstate')) }}>Clear filters</button></div>}
    <section className="dashboard-panel trace-log-panel"><div className="trace-table-heading"><div><div className="section-kicker">TRACE EVENT STREAM</div><h2>Collected records</h2><p>All four views are derived from events captured by experiments and attacker simulation.</p></div><a className="button button-primary trace-simulate-link" href="/attacker-simulation" onClick={(event) => onNavigate(event, '/attacker-simulation')}>Simulate Attacker <Icon name="arrow" size={13} /></a></div>
      <div className="trace-filters logs-advanced-filters"><label><span>Search all fields</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Action, target, topic, run…" /></label><label><span>Run</span><select value={runFilter} onChange={(event) => setRunFilter(event.target.value)}><option value="all">All runs</option>{state.runs.map((run) => <option key={run.id}>{run.id}</option>)}</select></label><label><span>Session</span><select value={sessionFilter} onChange={(event) => setSessionFilter(event.target.value)}><option value="">All sessions</option>{state.sessions.map((session) => <option key={session.id}>{session.id}</option>)}</select></label><label><span>Service</span><select value={serviceFilter} onChange={(event) => setServiceFilter(event.target.value)}><option value="all">All services</option>{[...new Set(state.traceEvents.map((event) => event.service).filter(Boolean))].map((service) => <option key={service}>{service}</option>)}</select></label><label><span>From</span><input type="date" value={dateFrom} onChange={(event) => setDateFrom(event.target.value)} /></label><label><span>To</span><input type="date" value={dateTo} onChange={(event) => setDateTo(event.target.value)} /></label><label><span>Source</span><select value={sourceFilter} onChange={(event) => setSourceFilter(event.target.value)}><option value="all">All sources</option><option value="observed_real">Observed real</option><option value="simulated">Simulated</option><option value="replayed">Replayed</option><option value="regenerated">Regenerated</option></select></label><span className="trace-result-count">{filteredEvents.length} events</span></div>
      <div className="logs-tabs" role="tablist" aria-label="Trace record types">{['Network Trace', 'Application Log', 'MQTT Log', 'Device Event'].map((tab) => <button type="button" role="tab" aria-selected={activeTab === tab} className={activeTab === tab ? 'logs-tab-active' : ''} key={tab} onClick={() => setActiveTab(tab)}>{tab}<span>{tab === 'Network Trace' || tab === 'Application Log' ? filteredEvents.length : tab === 'MQTT Log' ? mqttEvents.length : deviceEvents.length}</span></button>)}</div>
      <div className="table-wrap trace-table-wrap"><table className="data-table trace-events-table logs-detail-table"><thead>{activeTab === 'Network Trace' ? <tr><th>{sortButton('timestamp', 'Timestamp')}</th><th>Source IP</th><th>Destination IP</th><th>Protocol</th><th>Source Port</th><th>Destination Port</th><th>Packet Size</th><th>Flags</th><th>Run ID</th><th>Session ID</th></tr> : activeTab === 'Application Log' ? <tr><th>{sortButton('timestamp', 'Timestamp')}</th><th>Service</th><th>{sortButton('action', 'Event')}</th><th>Source / Type</th><th>Target</th><th>Result</th><th>Session ID</th><th>Run ID</th></tr> : activeTab === 'MQTT Log' ? <tr><th>{sortButton('timestamp', 'Timestamp')}</th><th>Client</th><th>Action</th><th>Topic</th><th>QoS</th><th>Payload Size</th><th>Result</th><th>Session ID</th></tr> : <tr><th>{sortButton('timestamp', 'Timestamp')}</th><th>Device</th><th>Action</th><th>State</th><th>Result</th><th>Session ID</th></tr>}</thead><tbody>{activeTab === 'Network Trace' ? filteredEvents.map((event) => <tr key={event.id}><td className="table-timestamp">{formatTimestamp(event.timestamp)}</td><td className="table-mono">{event.sourceIp ?? '—'}</td><td className="table-mono">{event.destinationIp ?? '192.0.2.10'}</td><td>{event.protocol ?? event.service ?? '—'}</td><td>{event.sourcePort ?? '—'}</td><td>{event.destinationPort ?? '—'}</td><td>{event.packetSize ? `${event.packetSize} B` : '—'}</td><td className="table-mono">{event.flags ?? '—'}</td><td className="table-mono">{event.runId}</td><td>{sessionCell(event.sessionId)}</td></tr>) : activeTab === 'Application Log' ? filteredEvents.map((event) => <tr key={event.id}><td className="table-timestamp">{formatTimestamp(event.timestamp)}</td><td>{event.service ?? '—'}</td><td><span className="trace-action-name">{event.action}</span></td><td className="logs-source-cell"><span>{event.sourceIp ?? '—'}</span>{sourceCell(event)}</td><td>{event.target ?? '—'}</td><td>{event.result ?? 'Observed'}</td><td>{sessionCell(event.sessionId)}</td><td className="table-mono">{event.runId}</td></tr>) : activeTab === 'MQTT Log' ? mqttEvents.map((event) => <tr key={event.id}><td className="table-timestamp">{formatTimestamp(event.timestamp)}</td><td className="table-mono">{event.sourceIp ?? '—'}</td><td><span className="trace-action-name">{event.action}</span></td><td>{event.topic ?? (event.action === 'topic_discovery' ? 'devices/# (discovery)' : '—')}</td><td>{event.qos ?? '—'}</td><td>{event.payloadSize === undefined ? '—' : `${event.payloadSize} B`}</td><td>{event.result ?? 'Observed'}</td><td>{sessionCell(event.sessionId)}</td></tr>) : deviceEvents.map((event) => <tr key={event.id}><td className="table-timestamp">{formatTimestamp(event.timestamp)}</td><td>{event.target ?? '—'}</td><td><span className="trace-action-name">{event.action}</span></td><td>{event.deviceState ?? 'event recorded'}</td><td>{event.result ?? 'Observed'}</td><td>{sessionCell(event.sessionId)}</td></tr>)}</tbody></table>{(activeTab === 'Network Trace' || activeTab === 'Application Log' ? filteredEvents.length : activeTab === 'MQTT Log' ? mqttEvents.length : deviceEvents.length) === 0 && <div className="trace-empty-state"><span><Icon name="activity" size={19} /></span><strong>No records in this view</strong><small>Choose another record type or create a matching simulation event.</small></div>}</div>
    </section>
    <section className="dashboard-panel logs-session-view"><div className="trace-table-heading"><div><div className="section-kicker">SESSION INSPECTOR</div><h2>Session timeline</h2><p>Inspect start, end, elapsed time and ordered events for a selected session.</p></div><select aria-label="Select session" value={selectedSessionId || sessionFilter} onChange={(event) => setSelectedSessionId(event.target.value)}><option value="">Select session</option>{sessionsForView.map((session) => <option key={session.id} value={session.id}>{session.id} · {session.runId}</option>)}</select></div>{selectedSession ? <><div className="logs-session-metrics"><span><small>SESSION ID</small><strong>{selectedSession.id}</strong></span><span><small>RUN ID</small><strong>{selectedSession.runId}</strong></span><span><small>START</small><strong>{sessionStart ? formatTimestamp(sessionStart) : '—'}</strong></span><span><small>END</small><strong>{sessionEnd ? formatTimestamp(sessionEnd) : 'In progress'}</strong></span><span><small>DURATION</small><strong>{sessionDuration}</strong></span></div><div className="logs-session-timeline">{selectedSessionEvents.length ? selectedSessionEvents.map((event, index) => <div className="logs-session-event" key={event.id}><span>{String(index + 1).padStart(2, '0')}</span><time>{formatTimestamp(event.timestamp)}</time><strong>{event.action}</strong><small>{event.service ?? event.protocol ?? 'Event'} · {event.result ?? 'Observed'}</small></div>) : <div className="trace-empty-inline">This session has no event records yet.</div>}</div></> : <div className="trace-empty-inline logs-session-empty">Select a session row above or use the session selector to inspect its timeline.</div>}</section>
  </div>
}

export function BehavioralAnalysisPage({ onNavigate }: TraceWorkspaceProps) {
  const state = usePrototypeState()
  const querySessionId = new URLSearchParams(window.location.search).get('session') ?? ''
  const [selectedSessionId, setSelectedSessionId] = useState(querySessionId || state.simulation.currentSessionId || state.sessions[0]?.id || '')
  const session = state.sessions.find((item) => item.id === selectedSessionId)
  const events = state.traceEvents.filter((event) => event.sessionId === selectedSessionId).sort((a, b) => a.timestamp.localeCompare(b.timestamp))
  const uniquePrimitives = new Set(events.map((event) => event.primitive)).size
  const sequence = events.map((event) => event.action)
  const sequenceObject = state.behavioralSequences.find((item) => item.sessionId === selectedSessionId)
  const actionFrequency = events.reduce<Record<string, number>>((counts, event) => ({ ...counts, [event.action]: (counts[event.action] ?? 0) + 1 }), {})
  const transitionFrequency = events.slice(0, -1).reduce<Record<string, number>>((counts, event, index) => { const key = `${event.action} → ${events[index + 1].action}`; return { ...counts, [key]: (counts[key] ?? 0) + 1 } }, {})
  const sessionDuration = events.length > 1 ? Math.max(0, (new Date(events.at(-1)!.timestamp).getTime() - new Date(events[0].timestamp).getTime()) / 1000) : 0
  const sessionDurations = state.sessions.map((item) => { const itemEvents = state.traceEvents.filter((event) => event.sessionId === item.id).sort((a, b) => a.timestamp.localeCompare(b.timestamp)); return { id: item.id, seconds: itemEvents.length > 1 ? Math.max(0, (new Date(itemEvents.at(-1)!.timestamp).getTime() - new Date(itemEvents[0].timestamp).getTime()) / 1000) : 0 } }).filter((item) => item.seconds > 0)
  const allTransitions = state.traceEvents.reduce<Record<string, number>>((counts, event) => { const ordered = state.traceEvents.filter((item) => item.sessionId === event.sessionId).sort((a, b) => a.timestamp.localeCompare(b.timestamp)); const index = ordered.findIndex((item) => item.id === event.id); const next = ordered[index + 1]; if (next) { const key = `${event.action} → ${next.action}`; counts[key] = (counts[key] ?? 0) + 1 } return counts }, {})
  const transitionProbabilities = Object.entries(allTransitions).map(([transition, count]) => { const sourceAction = transition.split(' → ')[0]; const sourceCount = Object.entries(allTransitions).filter(([key]) => key.startsWith(`${sourceAction} → `)).reduce((sum, [, value]) => sum + value, 0); return { transition, probability: sourceCount ? count / sourceCount : 0 } }).sort((a, b) => b.probability - a.probability)
  const primitiveMap: Record<string, string> = { service_discovery: 'Discovery', login_attempt: 'Authentication', device_discovery: 'Discovery', topic_discovery: 'Enumeration', mqtt_connect: 'Interaction', mqtt_subscribe: 'Interaction', mqtt_publish: 'Manipulation', disconnect: 'Exit' }

  return <div className="behavior-analysis-page">
    <section className="trace-workspace-summary"><span className="trace-workspace-icon analysis-workspace-icon"><Icon name="analysis" size={20} /></span><div><div className="section-kicker">SEQUENCE EXTRACTION</div><h2>Behavioral Analysis</h2><p>Sequences are derived directly from events captured in each Attack Session.</p></div><div className="trace-summary-stats"><span><small>SESSIONS</small><strong>{state.sessions.length}</strong></span><span><small>EVENTS</small><strong>{state.traceEvents.length}</strong></span><span><small>ACTIVE RUN</small><strong>{state.activeRunId}</strong></span></div></section>
    <div className="behavior-analysis-grid"><section className="dashboard-panel behavior-session-list"><div className="trace-table-heading"><div><div className="section-kicker">OBSERVED SESSIONS</div><h2>Behavior sources</h2></div><a className="text-link" href="/attacker-simulation" onClick={(event) => onNavigate(event, '/attacker-simulation')}>New simulation <Icon name="arrow" size={13} /></a></div><div className="behavior-session-options">{state.sessions.map((item) => { const eventCount = state.traceEvents.filter((event) => event.sessionId === item.id).length; return <button type="button" className={`behavior-session-option ${selectedSessionId === item.id ? 'behavior-session-selected' : ''}`} key={item.id} onClick={() => setSelectedSessionId(item.id)}><span className="session-option-mark"><Icon name="sessions" size={15} /></span><span className="session-option-copy"><strong>{item.id}</strong><small>{item.runId} · {item.service} · {item.sourceIp}</small></span><span className="session-option-count">{eventCount} EV</span></button> })}</div></section>
      <section className="dashboard-panel behavior-sequence-panel"><div className="trace-table-heading"><div><div className="section-kicker">EXTRACTED SEQUENCE</div><h2>{session ? session.id : 'Select a session'}</h2><p>{session ? `Run ${session.runId} · ${session.attackType} · ${session.target}` : 'Choose a session to inspect its event sequence.'}</p></div>{session && <SourceBadge source={events[0]?.source ?? 'observed_real'} />}</div>
        {session ? <><div className="behavior-sequence-metrics"><div><span>EVENT COUNT</span><strong>{events.length}</strong></div><div><span>UNIQUE PRIMITIVES</span><strong>{uniquePrimitives}</strong></div><div><span>DURATION</span><strong>{sessionDuration.toFixed(1)}s</strong></div></div><div className="analysis-sequence-list">{events.length === 0 ? <div className="trace-empty-inline">This session has no events yet.</div> : events.map((event, index) => <div className="analysis-sequence-row" key={event.id}><span className="analysis-step-index">{String(index + 1).padStart(2, '0')}</span><span className="analysis-step-kind">{primitiveMap[event.action] ?? event.primitive}</span><code>{event.action}</code><time>{formatTimestamp(event.timestamp)}</time></div>)}</div><div className="behavior-analysis-footer"><div><small>BEHAVIORAL SEQUENCE</small><strong>{sequence.length ? sequence.join(' → ') : 'No actions collected'}</strong></div><div className="analysis-actions"><button type="button" className="button button-primary" disabled={!events.length} onClick={() => extractBehavioralSequence(session.id)}>{sequenceObject ? `Refresh ${sequenceObject.id}` : 'Generate Behavioral Sequence'}</button><a className="button button-secondary" href={`/logs-traces?session=${session.id}`} onClick={(event) => onNavigate(event, `/logs-traces?session=${session.id}`)}>View Events <Icon name="arrow" size={13} /></a></div></div>{sequenceObject && <a className="sequence-object-link" href="/behavior-generator" onClick={(event) => onNavigate(event, '/behavior-generator')}><span><small>SEQUENCE OBJECT</small><strong>{sequenceObject.id}</strong></span><span>{sequenceObject.runId} → {sequenceObject.sessionId}</span><span>Open in Generator <Icon name="arrow" size={13} /></span></a>}</> : <div className="trace-empty-state"><span><Icon name="analysis" size={19} /></span><strong>No session selected</strong><small>Start an attacker simulation to create a sequence.</small></div>}
      </section></div>
    <section className="analysis-pipeline-panel dashboard-panel"><div className="trace-table-heading"><div><div className="section-kicker">EVENT PROCESSING</div><h2>Raw data to behavior features</h2></div></div><div className="analysis-pipeline">{['Raw Data', 'Events', 'Sessions', 'Behavioral Sequences', 'Features'].map((stage, index) => <div className="analysis-pipeline-stage" key={stage}><span>{index + 1}</span><strong>{stage}</strong><small>{index === 0 ? `${state.traceEvents.length} collected records` : index === 1 ? `${state.traceEvents.length} parsed events` : index === 2 ? `${state.sessions.length} sessions built` : index === 3 ? `${state.behavioralSequences.length} sequences extracted` : sequenceObject ? `${Object.keys(sequenceObject.features.actionFrequency).length} action features` : 'Awaiting extraction'}</small>{index < 4 && <i>→</i>}</div>)}</div><div className="analysis-processors">{[['Event Parser', state.traceEvents.length ? 'Ready' : 'Waiting'], ['Session Builder', state.sessions.length ? 'Ready' : 'Waiting'], ['Sequence Extractor', events.length ? 'Ready' : 'Waiting']].map(([name, status]) => <div className="analysis-processor" key={name}><span>{name}</span><strong className={status === 'Ready' ? 'process-ready' : 'process-waiting'}><i />{status}</strong></div>)}</div></section>
    <section className="analysis-analytics-grid"><div className="dashboard-panel analysis-chart-panel"><div className="trace-table-heading"><div><div className="section-kicker">ACTION FREQUENCY</div><h2>Action Distribution</h2></div></div>{Object.keys(actionFrequency).length ? Object.entries(actionFrequency).sort((a, b) => b[1] - a[1]).map(([action, count]) => <div className="analysis-bar-row" key={action}><code>{action}</code><span><i style={{ width: `${Math.max(5, count / Math.max(...Object.values(actionFrequency)) * 100)}%` }} /></span><strong>{count}</strong></div>) : <div className="trace-empty-inline">Select a session with events to calculate action frequency.</div>}</div><div className="dashboard-panel analysis-chart-panel"><div className="trace-table-heading"><div><div className="section-kicker">SEQUENTIAL PAIRS</div><h2>Transition Distribution</h2></div></div>{Object.keys(transitionFrequency).length ? Object.entries(transitionFrequency).sort((a, b) => b[1] - a[1]).map(([transition, count]) => <div className="analysis-bar-row" key={transition}><code>{transition}</code><span><i style={{ width: `${Math.max(5, count / Math.max(...Object.values(transitionFrequency)) * 100)}%` }} /></span><strong>{count}</strong></div>) : <div className="trace-empty-inline">At least two ordered events are needed to build transitions.</div>}</div><div className="dashboard-panel analysis-chart-panel"><div className="trace-table-heading"><div><div className="section-kicker">SESSION ELAPSED TIME</div><h2>Session Duration</h2></div></div>{sessionDurations.length ? sessionDurations.map((item) => <div className="analysis-bar-row" key={item.id}><code>{item.id}</code><span><i style={{ width: `${Math.max(5, item.seconds / Math.max(...sessionDurations.map((sessionItem) => sessionItem.seconds)) * 100)}%` }} /></span><strong>{item.seconds.toFixed(1)}s</strong></div>) : <div className="trace-empty-inline">Duration appears after a session contains multiple events.</div>}</div></section>
    <section className="analysis-ngram-grid"><div className="dashboard-panel analysis-chart-panel"><div className="trace-table-heading"><div><div className="section-kicker">N-GRAM EXAMPLES</div><h2>Observed action pairs</h2></div></div>{Object.entries(transitionFrequency).length ? Object.entries(transitionFrequency).map(([transition, count]) => <div className="analysis-pair-row" key={transition}><code>{transition}</code><strong>{count}×</strong></div>) : <div className="trace-empty-inline">N-grams will appear when the selected session has consecutive events.</div>}</div><div className="dashboard-panel analysis-chart-panel"><div className="trace-table-heading"><div><div className="section-kicker">CONDITIONAL TRANSITIONS</div><h2>Transition Probability</h2></div></div>{transitionProbabilities.length ? transitionProbabilities.map((item) => <div className="analysis-probability-row" key={item.transition}><span>{item.transition}</span><strong>{item.probability.toFixed(2)}</strong></div>) : <div className="trace-empty-inline">No cross-session transition observations yet.</div>}</div></section>
    <section className="dashboard-panel primitive-map-panel"><div className="trace-table-heading"><div><div className="section-kicker">SEMANTIC EVENT MAPPING</div><h2>Behavior primitive mapping</h2></div></div><div className="primitive-map-grid">{Object.entries(primitiveMap).map(([action, primitive]) => <div key={action}><code>{action}</code><span>→</span><strong>{primitive}</strong></div>)}</div></section>
  </div>
}

export function BehaviorGeneratorPage({ onNavigate }: TraceWorkspaceProps) {
  const state = usePrototypeState()
  const sequences = state.behavioralSequences
  const [selectedSequenceId, setSelectedSequenceId] = useState(sequences[0]?.id ?? '')
  const selectedSequence = sequences.find((item) => item.id === selectedSequenceId)
  const [mode, setMode] = useState<'G0 Exact Replay' | 'G1 Rule-Based Mutation' | 'G2 Probabilistic Generation'>('G0 Exact Replay')
  const [g1Actions, setG1Actions] = useState<string[]>(selectedSequence?.actions ?? [])
  const [g1Timing, setG1Timing] = useState<number[]>(selectedSequence?.actions.map(() => 1000) ?? [])
  const [target, setTarget] = useState('ESP32-01')
  const [addAction, setAddAction] = useState('reconnect')
  const [selectedIndex, setSelectedIndex] = useState(0)
  const [probabilityActions, setProbabilityActions] = useState<string[]>([])
  const [latestGenerationId, setLatestGenerationId] = useState('')
  const [notice, setNotice] = useState('')
  const session = selectedSequence ? state.sessions.find((item) => item.id === selectedSequence.sessionId) : undefined
  const sequenceEvents = selectedSequence ? selectedSequence.eventIds.map((id) => state.traceEvents.find((event) => event.id === id)).filter((event) => event !== undefined) : []
  const originalTiming = selectedSequence ? selectedSequence.actions.map((_, index) => index === 0 ? 0 : Math.max(0, new Date(sequenceEvents[index]?.timestamp ?? 0).getTime() - new Date(sequenceEvents[index - 1]?.timestamp ?? 0).getTime())) : []
  const transitions = selectedSequence?.features.transitionFrequency ?? {}
  const transitionTimingMs = selectedSequence?.features.transitionTimingMs ?? {}
  const outgoing = Object.entries(transitions).reduce<Record<string, { next: string; count: number }[]>>((map, [pair, count]) => { const [from, to] = pair.split(' → '); (map[from] ??= []).push({ next: to, count }); return map }, {})
  const transitionRows = Object.entries(transitions).map(([pair, count]) => { const [from, to] = pair.split(' → '); const denominator = (outgoing[from] ?? []).reduce((sum, item) => sum + item.count, 0); return { from, to, count, probability: denominator ? count / denominator : 0 } })
  const storedGeneration = sequences.flatMap((item) => state.generatedBehaviors.filter((generation) => generation.sourceSequenceId === item.id)).find((generation) => generation.id === latestGenerationId) ?? [...state.generatedBehaviors].reverse().find((generation) => generation.sourceSequenceId === selectedSequenceId)
  const generatedActions = mode === 'G0 Exact Replay' ? selectedSequence?.actions ?? [] : mode === 'G1 Rule-Based Mutation' ? g1Actions : probabilityActions.length ? probabilityActions : []
  const generatedTiming = mode === 'G0 Exact Replay' ? originalTiming : generatedActions.map((action, index) => mode === 'G1 Rule-Based Mutation' ? g1Timing[index] ?? 1000 : index === 0 ? originalTiming[0] ?? 0 : transitionTimingMs[`${generatedActions[index - 1]} → ${action}`] ?? 1000)
  const addableActions = ['service_discovery', 'login_attempt', 'device_discovery', 'topic_discovery', 'mqtt_connect', 'mqtt_subscribe', 'mqtt_publish', 'device_interaction', 'device_control', 'reconnect', 'disconnect', 'wait']
  function chooseSequence(sequenceId: string) { const next = sequences.find((item) => item.id === sequenceId); setSelectedSequenceId(sequenceId); setLatestGenerationId(''); setNotice(''); setProbabilityActions([]); setG1Actions(next?.actions ?? []); setG1Timing(next?.actions.map(() => 1000) ?? []); setTarget(state.sessions.find((sessionItem) => sessionItem.id === next?.sessionId)?.target ?? 'ESP32-01'); setSelectedIndex(0) }
  function updateG1Actions(next: string[]) { setG1Actions(next); setG1Timing(next.map((_, index) => g1Timing[index] ?? 1000)); setSelectedIndex((index) => Math.max(0, Math.min(index, next.length - 1))) }
  function generateProbabilitySequence() {
    if (!selectedSequence) return
    const result = generateProbabilisticActions(selectedSequence.id)
    setProbabilityActions(result)
    setMode('G2 Probabilistic Generation')
    setNotice('Generated a weighted walk using observed transitions from the selected sequence.')
  }
  function persistGeneration() {
    if (!selectedSequence || !generatedActions.length) { setNotice('Select a source sequence with actions before generating.'); return }
    const generation = createBehaviorGeneration({ sourceSequenceId: selectedSequence.id, generatorMode: mode, generatedActions, target, timingMs: generatedTiming })
    if (generation) { setLatestGenerationId(generation.id); setNotice(`${generation.id} generated from ${selectedSequence.id}.`) }
  }
  function resetDraft() { setMode('G0 Exact Replay'); setG1Actions(selectedSequence?.actions ?? []); setG1Timing(selectedSequence?.actions.map(() => 1000) ?? []); setTarget(session?.target ?? 'ESP32-01'); setProbabilityActions([]); setNotice('Draft reset to the observed sequence.') }

  return <div className="behavior-generator-page"><section className="trace-workspace-summary"><span className="trace-workspace-icon analysis-workspace-icon"><Icon name="spark" size={20} /></span><div><div className="section-kicker">TRACE-DRIVEN GENERATION</div><h2>Behavior Generator</h2><p>Generate related behaviors from an extracted sequence with full Run and Session traceability.</p></div><div className="trace-summary-stats"><span><small>INPUT SEQUENCES</small><strong>{sequences.length}</strong></span><span><small>GENERATIONS</small><strong>{state.generatedBehaviors.length}</strong></span></div></section>
    {!sequences.length ? <section className="dashboard-panel trace-empty-state generator-no-input"><span><Icon name="analysis" size={19} /></span><strong>No Behavioral Sequence available</strong><small>Collect session events, then open Behavioral Analysis and generate a Sequence Object.</small><a className="button button-primary" href="/behavioral-analysis" onClick={(event) => onNavigate(event, '/behavioral-analysis')}>Go to Behavioral Analysis <Icon name="arrow" size={13} /></a></section> : <>
      <section className="dashboard-panel generator-input-panel"><div className="trace-table-heading"><div><div className="section-kicker">SOURCE SEQUENCE</div><h2>Choose the observed behavior</h2><p>Input selectors stay linked to the sequence’s original Run and Session.</p></div><span className="trace-source trace-source-observed_real">Observed input</span></div><div className="generator-selectors"><label><span>Run</span><select value={selectedSequence?.runId ?? ''} onChange={(event) => { const next = sequences.find((item) => item.runId === event.target.value); if (next) chooseSequence(next.id) }}>{[...new Set(sequences.map((item) => item.runId))].map((runId) => <option key={runId}>{runId}</option>)}</select></label><label><span>Session</span><select value={selectedSequence?.sessionId ?? ''} onChange={(event) => { const next = sequences.find((item) => item.sessionId === event.target.value); if (next) chooseSequence(next.id) }}>{sequences.filter((item) => item.runId === selectedSequence?.runId).map((item) => <option key={item.sessionId}>{item.sessionId}</option>)}</select></label><label><span>Behavioral Sequence</span><select value={selectedSequenceId} onChange={(event) => chooseSequence(event.target.value)}>{sequences.filter((item) => item.sessionId === selectedSequence?.sessionId).map((item) => <option key={item.id}>{item.id}</option>)}</select></label><div className="generator-lineage"><small>LINEAGE</small><strong>{selectedSequence?.runId} → {selectedSequence?.sessionId} → {selectedSequence?.id}</strong></div></div>{selectedSequence && <div className="generator-original-sequence"><div><small>ORIGINAL SEQUENCE · {selectedSequence.id}</small><strong>{selectedSequence.actions.join(' → ')}</strong></div><span>{selectedSequence.features.eventCount} observed events</span></div>}</section>
      <section className="generator-workbench"><div className="generator-controls-column"><section className="dashboard-panel generator-mode-panel"><div className="trace-table-heading"><div><div className="section-kicker">GENERATOR MODE</div><h2>Choose a generation strategy</h2></div></div><div className="generator-mode-options">{(['G0 Exact Replay', 'G1 Rule-Based Mutation', 'G2 Probabilistic Generation'] as const).map((item) => <label className={mode === item ? 'generator-mode-selected' : ''} key={item}><input type="radio" name="generator-mode" checked={mode === item} onChange={() => { setMode(item); setProbabilityActions([]) }} /><span><strong>{item}</strong><small>{item.startsWith('G0') ? 'Preserve each observed action in order.' : item.startsWith('G1') ? 'Apply explicit action, target and timing mutations.' : 'Sample only observed transitions using their frequency.'}</small></span></label>)}</div></section>
        {mode === 'G1 Rule-Based Mutation' && <section className="dashboard-panel generator-mutation-panel"><div className="trace-table-heading"><div><div className="section-kicker">RULE-BASED MUTATION</div><h2>Mutation controls</h2><p>Changes update the generated preview immediately.</p></div></div><div className="generator-mutation-controls"><label><span>Action to add</span><select value={addAction} onChange={(event) => setAddAction(event.target.value)}>{addableActions.map((action) => <option key={action}>{action}</option>)}</select></label><button className="button button-secondary" onClick={() => updateG1Actions([...g1Actions, addAction])}>Add Action</button><label><span>Selected step</span><select value={selectedIndex} onChange={(event) => setSelectedIndex(Number(event.target.value))}>{g1Actions.map((action, index) => <option value={index} key={`${action}-${index}`}>{index + 1}. {action}</option>)}</select></label><div className="generator-action-buttons"><button className="button button-secondary" disabled={!g1Actions.length} onClick={() => updateG1Actions(g1Actions.filter((_, index) => index !== selectedIndex))}>Remove</button><button className="button button-secondary" disabled={!g1Actions.length} onClick={() => { const next = [...g1Actions]; next.splice(selectedIndex + 1, 0, next[selectedIndex]); updateG1Actions(next); setSelectedIndex(selectedIndex + 1) }}>Repeat</button><button className="button button-secondary" disabled={selectedIndex <= 0} onClick={() => { const next = [...g1Actions]; [next[selectedIndex - 1], next[selectedIndex]] = [next[selectedIndex], next[selectedIndex - 1]]; updateG1Actions(next); setSelectedIndex(selectedIndex - 1) }}>Move Up</button><button className="button button-secondary" disabled={selectedIndex >= g1Actions.length - 1} onClick={() => { const next = [...g1Actions]; [next[selectedIndex + 1], next[selectedIndex]] = [next[selectedIndex], next[selectedIndex + 1]]; updateG1Actions(next); setSelectedIndex(selectedIndex + 1) }}>Move Down</button></div><label><span>Change target</span><select value={target} onChange={(event) => setTarget(event.target.value)}>{['ESP32-01', 'ESP32-02', 'ESP32-03', 'MQTT Broker', 'SSH Service', 'HTTP Honeypot'].map((item) => <option key={item}>{item}</option>)}</select></label><label><span>Change timing (ms)</span><input type="number" min="0" value={g1Timing[selectedIndex] ?? 1000} onChange={(event) => setG1Timing((current) => current.map((timing, index) => index === selectedIndex ? Number(event.target.value) : timing))} /></label><div className="generator-action-buttons"><button className="button button-secondary" onClick={() => { updateG1Actions([...g1Actions, 'wait']); setG1Timing((current) => [...current, 1000]) }}>Add Wait</button><button className="button button-secondary" onClick={() => updateG1Actions([...g1Actions, 'reconnect'])}>Add Reconnect</button></div></div></section>}
        {mode === 'G2 Probabilistic Generation' && <section className="dashboard-panel generator-mutation-panel"><div className="trace-table-heading"><div><div className="section-kicker">OBSERVED TRANSITIONS</div><h2>Transition Matrix</h2><p>Probabilities are calculated from adjacent actions in {selectedSequence?.id}.</p></div><button className="button button-primary" disabled={!selectedSequence?.actions.length} onClick={generateProbabilitySequence}>Generate Sequence</button></div><div className="table-wrap generator-matrix-wrap"><table className="data-table"><thead><tr><th>From</th><th>To</th><th>Count</th><th>Probability</th></tr></thead><tbody>{transitionRows.map((item) => <tr key={`${item.from}-${item.to}`}><td className="table-mono">{item.from}</td><td className="table-mono">{item.to}</td><td>{item.count}</td><td>{item.probability.toFixed(2)}</td></tr>)}</tbody></table>{!transitionRows.length && <div className="trace-empty-inline">No observed transitions; this single-action sequence will retain its observed start action.</div>}</div></section>}
        </div><section className="dashboard-panel generator-preview-panel"><div className="trace-table-heading"><div><div className="section-kicker">GENERATION PREVIEW</div><h2>{mode}</h2><p>Output remains traceable to {selectedSequence?.id}.</p></div></div><div className="generator-preview-pair"><div><small>ORIGINAL</small><strong>{selectedSequence?.actions.join(' → ')}</strong></div><div><small>GENERATED</small>{generatedActions.length ? <div className="generated-sequence-steps">{generatedActions.map((action, index) => <span key={`${action}-${index}`}><small>STEP {String(index + 1).padStart(2, '0')} · {generatedTiming[index] ?? 0} MS · {target}</small><strong>{action}</strong></span>)}</div> : <strong>Press Generate Sequence to build the G2 preview.</strong>}</div></div><div className="generator-preview-meta"><span>Target <strong>{target}</strong></span><span>Steps <strong>{generatedActions.length}</strong></span><span>Timing <strong>{mode.startsWith('G0') ? 'Observed' : 'Mutated'}</strong></span></div><div className="generator-buttons"><button className="button button-primary" disabled={!generatedActions.length} onClick={persistGeneration}>Generate</button><button className="button button-secondary" disabled={!generatedActions.length} onClick={persistGeneration}>Regenerate</button><button className="button button-quiet" onClick={resetDraft}>Reset</button></div>{notice && <p className="generator-notice" role="status">{notice}</p>}{storedGeneration && <div className="generation-result"><div className="generation-result-heading"><div><small>GENERATION OBJECT</small><strong>{storedGeneration.id}</strong></div><span className="table-badge badge-complete"><i />{storedGeneration.status}</span></div><div className="generator-object-fields"><span>Source Sequence<strong>{storedGeneration.sourceSequenceId}</strong></span><span>Run / Session<strong>{storedGeneration.runId} / {storedGeneration.sourceSessionId}</strong></span><span>Mode<strong>{storedGeneration.generatorMode}</strong></span><span>Validation<strong>{storedGeneration.validation}</strong></span><span>Created<strong>{formatTimestamp(storedGeneration.createdAt)}</strong></span><span>Target<strong>{storedGeneration.target}</strong></span></div><div className="generator-result-actions"><button className="button button-secondary" onClick={() => { sendGenerationToValidator(storedGeneration.id); setNotice(`${storedGeneration.id} sent to Constraint Validator.`); const anchor = document.createElement('a'); anchor.href = '/constraint-validator'; onNavigate({ currentTarget: anchor, preventDefault() {}, metaKey: false, ctrlKey: false, shiftKey: false, altKey: false } as unknown as MouseEvent<HTMLAnchorElement>, '/constraint-validator') }}>Send to Validator <Icon name="arrow" size={13} /></button></div></div>}</section></section>
      <section className="dashboard-panel generation-history-panel"><div className="trace-table-heading"><div><div className="section-kicker">GENERATION HISTORY</div><h2>Generated behaviors</h2></div></div><div className="table-wrap trace-table-wrap"><table className="data-table attack-session-table"><thead><tr><th>Generation ID</th><th>Source Sequence</th><th>Run ID</th><th>Session ID</th><th>Mode</th><th>Actions</th><th>Status</th><th>Validation</th></tr></thead><tbody>{[...state.generatedBehaviors].reverse().map((generation) => <tr key={generation.id}><td className="table-mono">{generation.id}</td><td className="table-mono">{generation.sourceSequenceId}</td><td className="table-mono">{generation.runId}</td><td>{generation.sourceSessionId}</td><td>{generation.generatorMode}</td><td>{generation.generatedActions.join(' → ')}</td><td>{generation.status}</td><td>{generation.validation}</td></tr>)}</tbody></table>{!state.generatedBehaviors.length && <div className="trace-empty-inline">Generated outputs will be recorded here.</div>}</div></section>
    </>}
  </div>
}

export function ConstraintValidatorIntakePage({ onNavigate }: TraceWorkspaceProps) {
  const state = usePrototypeState()
  const generation = state.generatedBehaviors.find((item) => item.id === state.validatorGenerationId) ?? [...state.generatedBehaviors].reverse()[0]
  function forwardToReplay(generationId: string) {
    if (!requestValidatedReplay(generationId)) return
    const anchor = document.createElement('a')
    anchor.href = '/replay'
    onNavigate({ currentTarget: anchor, preventDefault() {}, metaKey: false, ctrlKey: false, shiftKey: false, altKey: false } as unknown as MouseEvent<HTMLAnchorElement>, '/replay')
  }
  return <div className="behavior-generator-page validator-page"><section className="trace-workspace-summary"><span className="trace-workspace-icon analysis-workspace-icon"><Icon name="shield" size={20} /></span><div><div className="section-kicker">SEMANTIC CONSTRAINTS</div><h2>Constraint Validator</h2><p>Check generated action ordering before a behavior can enter Controlled Replay.</p></div><div className="trace-summary-stats"><span><small>ACTIVE RULES</small><strong>{state.validatorRules.filter((rule) => rule.status === 'Active').length}</strong></span><span><small>GENERATIONS</small><strong>{state.generatedBehaviors.length}</strong></span></div></section>
    <section className="dashboard-panel validator-rules-panel"><div className="trace-table-heading"><div><div className="section-kicker">SEMANTIC RULES</div><h2>Constraint Rules</h2></div></div><div className="table-wrap trace-table-wrap"><table className="data-table"><thead><tr><th>Rule ID</th><th>Condition</th><th>Required Action</th><th>Status</th></tr></thead><tbody>{state.validatorRules.map((rule) => <tr key={rule.id}><td className="table-mono">{rule.id}</td><td className="table-mono">{rule.action}</td><td className="table-mono">{rule.requiredAction}</td><td><span className={`table-badge ${rule.status === 'Active' ? 'badge-active' : 'badge-complete'}`}><i />{rule.status}</span></td></tr>)}</tbody></table></div></section>
    {generation ? <section className="dashboard-panel validator-sequence-panel"><div className="trace-table-heading"><div><div className="section-kicker">GENERATION INPUT</div><h2>Validate Generated Sequence</h2><p>Trace: {generation.runId} → {generation.sourceSessionId} → {generation.sourceSequenceId}</p></div><label className="validator-generation-select"><span>Generation ID</span><select value={generation.id} onChange={(event) => sendGenerationToValidator(event.target.value)}>{[...state.generatedBehaviors].reverse().map((item) => <option key={item.id} value={item.id}>{item.id} · {item.sourceSequenceId}</option>)}</select></label></div><div className="validator-generation-meta"><span>Mode<strong>{generation.generatorMode}</strong></span><span>Created<strong>{formatTimestamp(generation.createdAt)}</strong></span><span>Target<strong>{generation.target}</strong></span><span>Generation Status<strong>{generation.status}</strong></span></div><div className="validator-action-sequence">{generation.generatedActions.map((action, index) => <span key={`${generation.id}-${index}`}><small>{String(index + 1).padStart(2, '0')}</small><code>{action}</code></span>)}</div><div className="validator-controls"><button className="button button-primary" onClick={() => validateGeneratedBehavior(generation.id)}>Validate Sequence</button><button className="button button-secondary" disabled={generation.validation !== 'Rejected'} onClick={() => fixGeneratedBehavior(generation.id)}>Fix Sequence</button><button className="button button-secondary" disabled={generation.validation !== 'Passed'} onClick={() => forwardToReplay(generation.id)}>Replay <Icon name="arrow" size={13} /></button></div>{generation.validation !== 'Pending' && <section className={`validation-result ${generation.validation === 'Passed' ? 'validation-result-valid' : 'validation-result-invalid'}`}><div className="validation-result-heading"><span>{generation.validation === 'Passed' ? '✓' : '!'}</span><div><strong>{generation.validation === 'Passed' ? 'VALID' : 'INVALID'}</strong><small>{generation.validatedAt ? `Validated ${formatTimestamp(generation.validatedAt)}` : ''}</small></div></div>{generation.validation === 'Passed' ? <ul><li>Constraint Passed</li><li>Ready for Replay</li></ul> : <div className="validation-errors"><strong>Reason</strong>{generation.validationErrors.map((error) => <p key={error}>{error}</p>)}</div>}{generation.validationWarnings.length > 0 && <div className="validation-warnings"><strong>Warnings</strong>{generation.validationWarnings.map((warning) => <p key={warning}>{warning}</p>)}</div>}</section>}</section> : <section className="dashboard-panel trace-empty-state generator-no-input"><span><Icon name="shield" size={19} /></span><strong>No Generation available</strong><small>Generate behavior in the Generator and select Send to Validator.</small><a className="button button-primary" href="/behavior-generator" onClick={(event) => onNavigate(event, '/behavior-generator')}>Open Behavior Generator <Icon name="arrow" size={13} /></a></section>}</div>
}

export function ReplayIntakePage({ onNavigate }: TraceWorkspaceProps) {
  const state = usePrototypeState()
  const selectedId = state.replayGenerationId ?? state.validatorGenerationId ?? [...state.generatedBehaviors].reverse()[0]?.id ?? ''
  const generation = state.generatedBehaviors.find((item) => item.id === selectedId)
  const replay = state.replays.find((item) => item.id === state.activeReplayId)
  const traces = replay ? state.generatedTraces.filter((trace) => trace.replayId === replay.id) : []
  const replayActive = replay ? ['Preparing', 'Connecting Testbed', 'Running', 'Paused', 'Collecting Trace'].includes(replay.status) : false
  const replaySteps = ['Preparing', 'Connecting Testbed', 'Replaying Actions', 'Collecting Trace', 'Completed']
  const replayStepIndex = replay ? replay.status === 'Running' || replay.status === 'Paused' ? 2 : replaySteps.indexOf(replay.status) : -1
  const canStart = generation?.validation === 'Passed' && !replayActive
  return <div className="behavior-generator-page replay-page"><section className="trace-workspace-summary"><span className="trace-workspace-icon"><Icon name="play" size={20} /></span><div><div className="section-kicker">CONTROLLED TESTBED SIMULATION</div><h2>Controlled Replay</h2><p>Replay a validated Generated Behavior in the local simulated IoT Testbed.</p></div><div className="trace-summary-stats"><span><small>REPLAYS</small><strong>{state.replays.length}</strong></span><span><small>REPLAY TRACES</small><strong>{state.generatedTraces.length}</strong></span></div></section>
    {state.generatedBehaviors.length ? <section className="dashboard-panel replay-input-panel"><div className="trace-table-heading"><div><div className="section-kicker">VALIDATED INPUT</div><h2>Generation to replay</h2><p>Replay Engine rejects any Generation without a passing Validation result.</p></div><label className="validator-generation-select"><span>Generation ID</span><select value={generation?.id ?? ''} onChange={(event) => selectReplayGeneration(event.target.value)} disabled={replayActive}>{[...state.generatedBehaviors].reverse().map((item) => <option key={item.id} value={item.id}>{item.id} · {item.validation} · {item.sourceSequenceId}</option>)}</select></label></div>{generation ? <><div className="replay-input-lineage"><span>{generation.runId}</span><i>→</i><span>{generation.sourceSessionId}</span><i>→</i><span>{generation.sourceSequenceId}</span><i>→</i><strong>{generation.id}</strong><span className={`table-badge ${generation.validation === 'Passed' ? 'badge-complete' : generation.validation === 'Rejected' ? 'badge-failed' : 'badge-active'}`}><i />{generation.validation === 'Passed' ? 'VALID' : generation.validation === 'Rejected' ? 'INVALID' : generation.validation}</span></div><div className="replay-source-actions">{generation.generatedActions.map((action, index) => <span key={`${generation.id}-${index}`}><small>{String(index + 1).padStart(2, '0')}</small><code>{action}</code></span>)}</div>{generation.validation === 'Rejected' && <div className="replay-validation-block"><strong>Replay disabled: Validation = INVALID</strong>{generation.validationErrors.map((error) => <small key={error}>{error}</small>)}<a href="/constraint-validator" onClick={(event) => onNavigate(event, '/constraint-validator')}>Fix in Constraint Validator <Icon name="arrow" size={12} /></a></div>}{generation.validation === 'Pending' && <div className="replay-validation-block replay-validation-pending"><strong>Validate this Generation before starting Replay.</strong><a href="/constraint-validator" onClick={(event) => onNavigate(event, '/constraint-validator')}>Open Constraint Validator <Icon name="arrow" size={12} /></a></div>}</> : null}</section> : <section className="dashboard-panel trace-empty-state generator-no-input"><span><Icon name="play" size={19} /></span><strong>No Generated Behavior to replay</strong><small>Generate behavior and validate it before starting Controlled Replay.</small><a className="button button-primary" href="/behavior-generator" onClick={(event) => onNavigate(event, '/behavior-generator')}>Open Behavior Generator <Icon name="arrow" size={13} /></a></section>}
    {generation && <section className="dashboard-panel replay-control-panel"><div className="trace-table-heading"><div><div className="section-kicker">REPLAY ENGINE</div><h2>Replay controls</h2><p>Actions are simulated in local Application State. No hardware or network service is contacted.</p></div><span className={`simulation-status-badge replay-status-${(replay?.status ?? 'idle').toLowerCase().replaceAll(' ', '-')}`}><i />{replay?.status ?? 'Idle'}</span></div><div className="replay-flow-steps">{replaySteps.map((step, index) => <div className={`${replayStepIndex === index ? 'replay-step-current' : ''} ${replayStepIndex > index ? 'replay-step-complete' : ''}`} key={step}><span>{replayStepIndex > index ? '✓' : String(index + 1).padStart(2, '0')}</span><strong>{step}</strong>{index < replaySteps.length - 1 && <i>→</i>}</div>)}</div><div className="replay-controls"><button className="button button-primary" onClick={() => startReplay(generation.id)} disabled={!canStart}><Icon name="play" size={13} />Start Replay</button><button className="button button-secondary" onClick={pauseReplay} disabled={replay?.status !== 'Running'}>Pause</button><button className="button button-secondary" onClick={resumeReplay} disabled={replay?.status !== 'Paused'}>Resume</button><button className="button button-secondary" onClick={stopReplay} disabled={!replayActive}><span className="stop-square" />Stop</button><button className="button button-quiet" onClick={resetReplay} disabled={!replay}>Reset</button></div>{replay && <div className="replay-run-meta"><span>Replay ID<strong>{replay.id}</strong></span><span>Generation<strong>{replay.generationId}</strong></span><span>Protocol<strong>{replay.protocol}</strong></span><span>Target<strong>{replay.target}</strong></span><span>Started<strong>{formatTimestamp(replay.startedAt)}</strong></span><span>Completed<strong>{replay.completedAt ? formatTimestamp(replay.completedAt) : '—'}</strong></span></div>}</section>}
    {replay && <section className="dashboard-panel replay-trace-panel"><div className="trace-table-heading"><div><div className="section-kicker">GENERATED TRACE · SOURCE REPLAYED</div><h2>{replay.id} Trace</h2><p>Replay actions remain classified separately from observed_real and regenerated records.</p></div><span className="trace-source trace-source-replayed">replayed</span></div><div className="table-wrap trace-table-wrap"><table className="data-table attack-session-table replay-trace-table"><thead><tr><th>Replay ID</th><th>Generation ID</th><th>Timestamp</th><th>Action</th><th>Target</th><th>Protocol</th><th>Source</th><th>Status</th></tr></thead><tbody>{traces.map((trace) => <tr key={trace.id}><td className="table-mono">{trace.replayId}</td><td className="table-mono">{trace.generationId}</td><td className="table-timestamp">{formatTimestamp(trace.timestamp)}</td><td className="trace-action-name">{trace.action}</td><td>{trace.target}</td><td>{trace.protocol}</td><td><SourceBadge source={trace.source} /></td><td>{trace.status}</td></tr>)}</tbody></table>{!traces.length && <div className="trace-empty-inline">Replay Trace records will appear as actions execute.</div>}</div></section>}
  </div>
}

export function AttackSessionsPage({ onNavigate }: TraceWorkspaceProps) {
  const state = usePrototypeState()
  const querySessionId = new URLSearchParams(window.location.search).get('session')
  const sessions = [...state.sessions].reverse()
  return <div className="attack-sessions-page">
    <section className="trace-workspace-summary"><span className="trace-workspace-icon session-workspace-icon"><Icon name="sessions" size={20} /></span><div><div className="section-kicker">SESSION INDEX</div><h2>Attack Sessions</h2><p>Every session is associated with its originating experiment run.</p></div><div className="trace-summary-stats"><span><small>TOTAL SESSIONS</small><strong>{state.sessions.length}</strong></span><span><small>RUNS WITH SESSIONS</small><strong>{new Set(state.sessions.map((item) => item.runId)).size}</strong></span><span><small>ACTIVE RUN</small><strong>{state.activeRunId}</strong></span></div></section>
    <section className="dashboard-panel trace-log-panel"><div className="trace-table-heading"><div><div className="section-kicker">ATTACK ACTIVITY</div><h2>Session registry</h2><p>Select a session to view its collected events.</p></div><a className="button button-primary trace-simulate-link" href="/attacker-simulation" onClick={(event) => onNavigate(event, '/attacker-simulation')}>Start Simulation <Icon name="arrow" size={13} /></a></div><div className="table-wrap trace-table-wrap"><table className="data-table attack-session-table"><thead><tr><th>Session ID</th><th>Run ID</th><th>Source IP</th><th>Target</th><th>Service</th><th>Attack Type</th><th>Events</th><th>Status</th><th>Source</th></tr></thead><tbody>{sessions.map((item) => <tr className={querySessionId === item.id ? 'trace-highlight-row' : ''} key={item.id}><td><a className="table-primary-link" href={`/logs-traces?session=${item.id}`} onClick={(event) => onNavigate(event, `/logs-traces?session=${item.id}`)}>{item.id}<Icon name="arrow" size={12} /></a></td><td><a className="table-mono-link" href="/experiment" onClick={(event) => onNavigate(event, '/experiment')}>{item.runId}</a></td><td className="table-mono">{item.sourceIp}</td><td>{item.target}</td><td>{item.service}</td><td>{item.attackType}</td><td>{state.traceEvents.filter((trace) => trace.sessionId === item.id).length}</td><td><span className={`table-badge ${item.status === 'Active' ? 'badge-active' : 'badge-complete'}`}><i />{item.status}</span></td><td><SourceBadge source={item.id.startsWith('SESSION-') ? 'simulated' : 'observed_real'} /></td></tr>)}</tbody></table>{sessions.length === 0 && <div className="trace-empty-state"><span><Icon name="sessions" size={19} /></span><strong>No sessions collected</strong><small>Start a simulation to create the first attacker session.</small></div>}</div></section>
  </div>
}
